package main

import (
	"encoding/hex"

	z "gno.land/p/onbloc/ibc/union/zkgm"
	types "gno.land/p/onbloc/ibc/union/types"
	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

func main() {
	channelId := types.ChannelId(51)
	quoteTokenHex := "12468e316cb7f3e23fcf096f39498bf8c2ff7f0a"
	recipient := "g18tml4dnf8rmexdgkcj8ukgdjtcsz8kk0rww4aw"

	quoteToken, err := hex.DecodeString(quoteTokenHex)
	if err != nil {
		panic(err)
	}

	balance, err := zkgm.GetChannelBalanceV2(channelId, u256.Zero(), "ugnot", quoteToken)
	if err != nil {
		println("channel_balance_err", err.Error())
		return
	}
	println("channel_balance", balance.ToString())

	order := z.TokenOrderV2{
		BaseToken:   []byte("ugnot"),
		QuoteToken:  quoteToken,
		BaseAmount:  balance,
		QuoteAmount: u256.Zero(),
		Receiver:    []byte(recipient),
		Kind:        z.TOKEN_ORDER_KIND_ESCROW,
	}

	operand, err := z.EncodeTokenOrderV2(order)
	if err != nil {
		panic(err)
	}

	println("operand_hex", hex.EncodeToString(operand))
}

